#!/usr/bin/env node
// Mines repeated string literals and directory import edges from a source
// tree, and emits centralize-domain-literals configuration from constants
// modules. Node built-ins only; no dependencies.
//
//   node mine-literals.mjs <src-dir> [--min-files 2] [--edges]
//   node mine-literals.mjs --emit <constants-file-or-glob>...
import { readdirSync, readFileSync, statSync } from "node:fs";
import path from "node:path";

const args = process.argv.slice(2);
const flag = (name) => args.includes(name);
const option = (name, fallback) => {
  const index = args.indexOf(name);
  return index === -1 ? fallback : args[index + 1];
};

const sourceExtensions = new Set([".ts", ".tsx", ".js", ".jsx", ".mjs", ".mts"]);
const isTestPath = (file) =>
  /(?:^|\/)(?:__tests__|__mocks__|test-utils|testing)\//u.test(file) ||
  /\.(?:test|spec|stories)\.[cm]?[jt]sx?$/u.test(file);

const walk = (root, files = []) => {
  for (const entry of readdirSync(root)) {
    if (entry === "node_modules" || entry.startsWith(".")) continue;
    const full = path.join(root, entry);
    if (statSync(full).isDirectory()) walk(full, files);
    else if (sourceExtensions.has(path.extname(full))) files.push(full);
  }
  return files;
};

const expandGlobs = (patterns) => {
  const files = [];
  for (const pattern of patterns) {
    const [base] = pattern.split(/[*{]/u);
    const root = base.endsWith("/") ? base : path.dirname(base);
    const matcher = new RegExp(
      `^${pattern
        .replaceAll(".", "\\.")
        .replaceAll("**/", "(?:.*/)?")
        .replaceAll("*", "[^/]*")}$`,
      "u",
    );
    try {
      if (statSync(root).isFile()) {
        files.push(root);
        continue;
      }
      for (const file of walk(root)) if (matcher.test(file)) files.push(file);
    } catch {
      // Missing paths are reported by the caller through an empty result.
    }
  }
  return files;
};

// Strips comments, import/export sources, property keys, and type positions
// well enough for candidate mining. This is a heuristic, not a parser: the
// inventory step classifies the survivors by hand.
const literalPattern = /(["'])((?:\\.|(?!\1)[^\\\n])*)\1/gu;
const stripNoise = (source) =>
  source
    .replace(/\/\*[\s\S]*?\*\//gu, "")
    .replace(/(^|[^:])\/\/.*$/gmu, "$1")
    .replace(/\b(?:import|export)\b[^;]*?\bfrom\s*(["'])[^"']*\1/gu, "")
    .replace(/\bimport\s*\(\s*(["'])[^"']*\1\s*\)/gu, "")
    .replace(/\brequire\s*\(\s*(["'])[^"']*\1\s*\)/gu, "")
    .replace(/(["'])[^"'\n]*\1\s*:/gu, "")
    .replace(/:\s*(["'])[^"'\n]*\1(?=\s*[;|&)>\],=])/gu, "");

const looksLikeProse = (value) =>
  value.length === 0 ||
  value.length > 48 ||
  /\s.*\s/u.test(value.trim()) ||
  /[.!?]$/u.test(value) ||
  /^[A-Z][a-z]+ [a-z]/u.test(value);

const mine = (sourceDir, minimumFiles) => {
  const occurrences = new Map();
  for (const file of walk(sourceDir)) {
    if (isTestPath(file)) continue;
    const source = stripNoise(readFileSync(file, "utf8"));
    for (const match of source.matchAll(literalPattern)) {
      const value = match[2];
      if (looksLikeProse(value)) continue;
      const files = occurrences.get(value) ?? new Set();
      files.add(file);
      occurrences.set(value, files);
    }
  }
  const rows = [...occurrences.entries()]
    .filter(([, files]) => files.size >= minimumFiles)
    .sort((a, b) => b[1].size - a[1].size || a[0].localeCompare(b[0]));
  for (const [value, files] of rows) {
    const list = [...files].slice(0, 3).join(", ");
    const more = files.size > 3 ? `, +${files.size - 3}` : "";
    console.log(
      `${JSON.stringify(value).padEnd(28)} ${String(files.size).padStart(3)} files  ${list}${more}`,
    );
  }
  if (rows.length === 0) console.log("No repeated literals found.");
};

const edges = (sourceDir) => {
  const moduleOf = (file) => {
    const relative = path.relative(sourceDir, file).split(path.sep);
    return relative[0] === "features" && relative.length > 2
      ? `features/${relative[1]}`
      : relative[0];
  };
  const seen = new Map();
  for (const file of walk(sourceDir)) {
    if (isTestPath(file)) continue;
    const source = readFileSync(file, "utf8");
    for (const match of source.matchAll(/\bfrom\s*["']([^"']+)["']/gu)) {
      const specifier = match[1];
      let target;
      if (specifier.startsWith(".")) {
        target = path.resolve(path.dirname(file), specifier);
      } else if (specifier.startsWith("@/")) {
        target = path.resolve(sourceDir, specifier.slice(2));
      } else continue;
      if (!target.startsWith(path.resolve(sourceDir))) continue;
      const from = moduleOf(file);
      const to = moduleOf(target);
      if (from === to) continue;
      const key = `${from} -> ${to}`;
      seen.set(key, (seen.get(key) ?? 0) + 1);
    }
  }
  console.log("\nImport edges between top-level modules (count):");
  for (const [edge, count] of [...seen.entries()].sort()) {
    console.log(`  ${edge.padEnd(48)} ${count}`);
  }
};

const emit = (patterns) => {
  const files = expandGlobs(patterns);
  if (files.length === 0) {
    console.error("No constants modules matched.");
    process.exit(1);
  }
  const literals = [];
  const objectPattern =
    /export\s+const\s+([A-Z][A-Z0-9_]*)\s*=\s*\{([\s\S]*?)\}\s*as\s+const/gu;
  const entryPattern = /^\s*([A-Za-z_$][\w$]*)\s*:\s*(["'])((?:\\.|(?!\2)[^\\\n])*)\2/gmu;
  for (const file of files) {
    const source = readFileSync(file, "utf8");
    for (const object of source.matchAll(objectPattern)) {
      for (const entry of object[2].matchAll(entryPattern)) {
        literals.push({
          replacement: `${object[1]}.${entry[1]}`,
          value: entry[3],
        });
      }
    }
  }
  const config = {
    constantsFiles: patterns,
    literals: literals.sort((a, b) => a.value.localeCompare(b.value)),
  };
  console.log(
    `"code-architecture/centralize-domain-literals": ${JSON.stringify(["error", config], null, 2)},`,
  );
};

if (flag("--emit")) {
  emit(args.filter((argument) => argument !== "--emit"));
} else {
  const sourceDir = args.find((argument) => !argument.startsWith("--")) ?? "src";
  mine(sourceDir, Number(option("--min-files", "2")));
  if (flag("--edges")) edges(sourceDir);
}

